# -*- coding: utf-8 -*-
"""Writes SOURCES_REPORT.md, README.md, QA_SUMMARY.md and registers the two in-book appendix pages (report, tech)."""
import os, re, json, zipfile
import markdown


def build_reports(g):
    HERE, ROOT = g['HERE'], g['ROOT']
    FLAGS, MEDIA, ITEMS, WITHHELD, YOUTUBE, BLOCK_ROUTE, SRC = g['FLAGS'], g['MEDIA'], g['ITEMS'], g['WITHHELD'], g['YOUTUBE'], g['BLOCK_ROUTE'], g['SRC']
    clean = g['clean']
    qa = {}
    qp = os.path.join(HERE, 'data', 'qa.json')
    if os.path.exists(qp):
        qa = json.load(open(qp, encoding='utf8'))

    # unused external relationships in the docx
    z = zipfile.ZipFile(os.path.join(HERE, 'source', 'sawti-arabi-source.docx'))
    rels = z.read('word/_rels/document.xml.rels').decode()
    ext = re.findall(r'Target="([^"]+)"[^>]*TargetMode="External"', rels) + re.findall(r'TargetMode="External"[^>]*Target="([^"]+)"', rels)
    used_ids = set(YOUTUBE.values())
    unused_yt = [u for u in ext if 'youtube' in u and u.split('v=')[-1] not in used_ids]

    media_notes = [m for m in MEDIA if m['note']]
    L = []
    A = L.append
    A('# Sources report — «صوتي عربي» interactive book\n')
    A('_Generated by `_generator/build.py`. The same text appears inside the book (Appendix → Sources report)._\n')
    A('## 1. What was supplied, and what was added\n')
    A('**Supplied by you (and used):**\n')
    A('- The Word file `ccf475a2-____________________.docx` (course text: %d body blocks, 47 images embedded).' % len(SRC))
    A('- `Audiovisuals.zip`: 64 audio/video files. **63 are used**, mapped to the exercises *by content* (see §3). One (`مخرج ق 2.mp4`) is a byte-identical duplicate of `مخرج ق 1.mp4` and is not used.')
    A('- The title font `TSHiba-Bold.otf`, used for titles only (see §6).')
    A('- 7 YouTube links written in the Word file, embedded (loaded only when the reader presses the button) with a direct link; one third-party link attached to the word «هيلا» is shown as a link, unchecked.\n')
    A('**Added by this edition (always labelled “Educational addition” on the page):** item introductions, pre-listening/reading prompts, six open questions per item with typed labels and jump buttons, cultural-comparison prompts, English glosses of word-table entries and of the longer texts, expression sets, proficiency maps, final tasks, the articulation reference with its exercise, the vocabulary index, the interface text, and the visual design.\n')
    A('**Quoted from the course file unchanged and labelled “From the course materials”:** all objectives, instructions, word tables, verb tables, poems and speech that are not withheld (§4). A programmatic check (`verify.py`) confirms every non-empty line of the Word file is present on a page except the withheld blocks%s.\n' % (
        (' — result: **%s**' % qa['fidelity']) if qa.get('fidelity') else ''))
    A('## 2. Structural gaps in the materials (disclosed, not hidden)\n')
    for s in [
        'No ACTFL (or other framework) PDFs were attached, so no framework descriptors are quoted; the proficiency maps use the course’s own objectives (see the “Proficiency framework” appendix).',
        'No introductory HTML page, no connectors-page tool, no cover image and no credits file were supplied. The cover uses a drawn sound-wave motif; the credit line is taken from the footer of the Word file (four authors); the connectors-equivalent is the “Expressions for discussion” page (educational addition).',
        'Unit 2 (Lessons 6–8) has no local audio/video in the zip; its listening relies on the YouTube links in the Word file.',
        'The Word file names no author or date on its first page. The year 2016 comes from the document properties and is used in the copyright line.',
        'The unit-objectives table (Unit 1/Unit 2 labels) is laid out ambiguously in the Word file; the five sound-related bullets are placed under Unit 1 and the two long-text bullets under Unit 2 because of their content.',
        'Lesson 1 has one item (1.6, “Aṣīr al-Kutub”) whose supplied transcript is deliberately not shown (§4).',
        'The ACTFL-style “can-do” statements, glosses and questions are written by the edition, not taken from the course; they are suggestions for a teacher to review.']:
        A('- ' + s)
    A('')
    A('## 3. Audio/video: mapping and mismatches\n')
    A('File names and numbering in the zip do not always match the exercise numbers in the Word file, so each file was matched to an exercise by listening/viewing its content where possible (first frame, title card) and by its position in the lesson. Notes recorded for individual files:\n')
    for m in media_notes:
        A('- `%s` → item %s: %s' % (m['id'], m['item'], m['note']))
    A('- `l3-ayn-clip` (`ع متقطع.mp4`) was filed in the Lesson 1 folder of the zip; it is placed in Lesson 3 item 3.1 by its content.')
    A('')
    A('**Seek buttons** exist only for times written in the Word file: the Aṣīr al-Kutub episode (0:00 and 2:00), the lām video (0:00, 3:00, 3:02, 3:20) and the rāʾ video (0:00, 1:00, 5:03). The file writes two of these as “3:2” and “5:3” (flagged below). No timestamps were invented.\n')
    A('**Re-encoded media.** The Aṣīr al-Kutub episode was 158 MB in the zip (52 min). It was re-encoded to 480×270 H.264/AAC (about 39 MB) so that the book stays below GitHub’s 100 MB per-file limit. The exercise uses only minutes 0:00–2:00. Everything else is copied byte-for-byte (video sizes are listed in `_generator/media_map.py`).\n')
    A('## 4. Withheld texts\n')
    A('| Block | Content | Reason |\n|---|---|---|')
    seen = set()
    for i, w in sorted(WITHHELD.items()):
        if w['key'] in seen:
            continue
        seen.add(w['key'])
        A('| %s | %s | %s |' % (w['key'], w['label_en'], 'supplied transcript; shown to students only if the teacher chooses' if w['kind'] == 'transcript' else 'modern copyrighted lyrics/poem; the book links to the video instead'))
    A('')
    A('**Private-text slot.** If you own or are licensed to show one of the copyrighted texts, save it as UTF-8 in `_generator/data/private_texts/<key>.txt` (one line per verse; the key is in the table above) and run `python3 -I _generator/build.py`. The text then replaces the “withheld” card. Do not publish a repository containing such a file unless you hold the rights.\n')
    A('## 5. Source errors found in the Word file (flagged, never silently fixed)\n')
    A('The book prints the text **as supplied** and puts a ⚑ marker next to it; clicking the marker shows the problem and the proposed fix. The list is not exhaustive. %d flags:\n' % len(FLAGS))
    A('| # | Where | Supplied text | Problem | Proposed fix |\n|---|---|---|---|---|')
    for n, f in enumerate(FLAGS, 1):
        rt = BLOCK_ROUTE.get(f['block'], '')
        A('| %d | `#/%s` (block %d) | %s | %s | %s |' % (n, rt, f['block'], f['text'].replace('|', '\\|'), f['note'].replace('|', '\\|'), f['fix'].replace('|', '\\|')))
    A('')
    A('## 6. Fonts, images, licences\n')
    A('- **Titles:** TS Hiba Bold, supplied by you. Its licence was not supplied; the font file’s own metadata says “All rights reserved”. **Please confirm you may publish it** (for example on GitHub Pages). If not, delete `assets/fonts/TSHiba-Bold.otf` and the `TS Hiba` rule in `assets/css/fonts.css`; titles fall back to Amiri.')
    A('- **Body fonts (self-hosted, SIL Open Font License 1.1):** Amiri, IBM Plex Sans Arabic, Noto Serif (npm `@fontsource` 5.3.0). The Word file mentions Sakkal Majalla; it is not redistributable, so Amiri replaces it.')
    A('- **Images:** the 47 pictures in `assets/img/` are extracted unchanged from the Word file. Their authorship and licences are not stated in the file and are unknown; they are shown only where they appear in the course text.')
    A('- **Cover motif:** an original inline SVG drawn for this edition.\n')
    A('## 7. Data, privacy and external services\n')
    A('Nothing is sent anywhere by the book. Answers, stars, progress and settings are stored in the reader’s own browser (`localStorage`, always inside try/catch) and can be downloaded as a text file. YouTube is loaded only after the reader presses the load button, from `youtube-nocookie.com`. **When the book is opened from `file://` YouTube may refuse to play (error 153) because there is no web origin; host the folder on a web server or GitHub Pages.**\n')
    A('## 8. Unused material in the Word file\n')
    A('The Word file contains %d further YouTube hyperlink relationships that are not attached to any visible text (probably left over from earlier drafts). They are not used. Video ids: %s.\n' % (len(unused_yt), ', '.join(u.split('v=')[-1] for u in unused_yt)))
    A('## 9. Rebuild and publish\n')
    A('1. `python3 -I _generator/build.py` regenerates `index.html`-data (`assets/js/data.js`) from the Word file in `_generator/source/`. Fonts: `prepare_fonts.py`; media: `prepare_media.py` (needs the zip; paths inside).')
    A('2. GitHub Pages: upload the folder contents so that `index.html` sits at the repository root; a public repository is needed on the free plan; each file must be under 100 MB (the largest is the re-encoded 39 MB video); total site size should stay below 1 GB.\n')
    md_report = '\n'.join(L)
    open(os.path.join(ROOT, 'SOURCES_REPORT.md'), 'w', encoding='utf8').write(md_report)

    # --- README ------------------------------------------------------------------------------------------------------
    R = ['# صوتي عربي — interactive virtual book\n',
         'A static, offline-capable interactive edition of the course materials «صوتي عربي: فصحى – عامية – دارجة». Open `index.html` in a browser (a web server or GitHub Pages is needed for YouTube playback).\n',
         '## Contents of the folder\n',
         '- `index.html` — the page shell\n- `assets/` — css, js (app + generated `data.js`), fonts, images extracted from the Word file, audio/video\n- `_generator/` — everything needed to rebuild (Python 3, `lxml`, `markdown`)\n- `SOURCES_REPORT.md`, `QA_SUMMARY.md` — reports\n',
         '## Rebuild\n',
         '```\npython3 -I _generator/parse_docx.py   # Word file -> data/source.json\npython3 -I _generator/build.py        # pages -> assets/js/data.js, reports\npython3 -I _generator/verify.py       # source-fidelity check\n```\n',
         '## Publishing on GitHub Pages\n',
         'Put the folder contents at the repository root (public repository on the free plan), then Settings → Pages → deploy from the `main` branch root. Check the TS Hiba licence first (see `SOURCES_REPORT.md` §6).\n',
         '## Editing\n',
         '- Questions and prompts: `_generator/edu_items.py`; unit-level pages: `edu_units.py`; word glosses: `data/glosses.txt`; text glossaries: `edu_gloss.py`.\n- Source-error flags: `data_flags.py` (the Word text is never edited).\n- Withheld texts and the private-text slot: `SOURCES_REPORT.md` §4.\n']
    open(os.path.join(ROOT, 'README.md'), 'w', encoding='utf8').write('\n'.join(R))

    # --- QA summary ------------------------------------------------------------------------------------------------
    Q = ['# QA summary\n']
    if qa:
        Q.append('Run on %s with headless Chromium (Playwright), served from a local web server and also opened from `file://`.\n' % qa.get('date', ''))
        Q.append('## Tested and passing\n')
        for s in qa.get('passed', []):
            Q.append('- ' + s)
        Q.append('\n## Found and fixed during QA\n')
        for s in qa.get('fixed', []) or ['(none recorded)']:
            Q.append('- ' + s)
        Q.append('\n## Not tested / cannot be verified here\n')
        for s in qa.get('untested', []):
            Q.append('- ' + s)
    else:
        Q.append('QA has not been run yet for this build.')
    qa_md = '\n'.join(Q)
    open(os.path.join(ROOT, 'QA_SUMMARY.md'), 'w', encoding='utf8').write(qa_md)

    conv = lambda t: markdown.markdown(t, extensions=['tables'])
    rep_html = '<article class="page appendix prose"><nav class="crumbs"><a href="#/">الغلاف</a> › <span>تقرير المصادر</span></nav><h1 class="ttl" lang="ar">ملحق: تقرير المصادر</h1><p class="item-en" lang="en" dir="ltr">Appendix: sources report</p><div class="md" lang="en" dir="ltr">%s</div></article>' % conv(md_report.split('\n', 2)[2])
    tech_html = ('<article class="page appendix prose"><nav class="crumbs"><a href="#/">الغلاف</a> › <span>ملاحظات تقنية</span></nav><h1 class="ttl" lang="ar">ملحق: ملاحظات تقنية</h1><p class="item-en" lang="en" dir="ltr">Appendix: technical notes and QA</p><div class="md" lang="en" dir="ltr">%s</div></article>'
                 % conv('\n'.join(R[2:]) + '\n\n' + qa_md.replace('# QA summary', '## QA summary')))
    g['register']('appendix/report', 'ملحق: تقرير المصادر', 'Appendix: sources report', rep_html, 'appendix')
    g['register']('appendix/tech', 'ملحق: ملاحظات تقنية', 'Appendix: technical notes and QA', tech_html, 'appendix')
